// Normaliza lo que pide el agente: tipo de evento y si solo quiere los próximos
const TIPOS = [
  'inscripcion', 'prueba_diagnostica', 'resultados', 'inicio_curso', 'fin_curso',
  'evaluacion', 'retiro', 'certificacion', 'matricula', 'inicio_clases', 'receso',
];
const SINONIMOS = {
  inscripciones: 'inscripcion',
  prueba: 'prueba_diagnostica',
  diagnostica: 'prueba_diagnostica',
  pruebas_diagnosticas: 'prueba_diagnostica',
  inicio: 'inicio_curso',
  inicio_cursos: 'inicio_curso',
  inicio_de_cursos: 'inicio_curso',
  cierre: 'fin_curso',
  fin_cursos: 'fin_curso',
  insignia: 'certificacion',
  insignias: 'certificacion',
  matriculas: 'matricula',
  vacaciones: 'receso',
};

const entrada = $input.first().json;
const texto = String(entrada.tipo_evento ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().trim().replace(/[\s-]+/g, '_');

let tipo = null;
if (texto && !['todos', 'todo', 'cualquiera', 'null', 'ninguno'].includes(texto)) {
  tipo = TIPOS.includes(texto) ? texto : (SINONIMOS[texto] ?? null);
}

const soloProximos = !(entrada.solo_proximos === false || String(entrada.solo_proximos).toLowerCase() === 'false');

return [{ json: { tipo_evento: tipo, tipo_solicitado: texto || null, solo_proximos: soloProximos } }];

// Filtra los eventos de la hoja y calcula el estado de cada uno
// respecto a la fecha de hoy en Bogotá. Las fechas están como texto AAAA-MM-DD.
const parametros = $('Normalizar parámetros').first().json;
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
const FECHA = /^\d{4}-\d{2}-\d{2}$/;
const DIA = 24 * 60 * 60 * 1000;

let eventos = $input.all()
  .map((item) => item.json)
  .filter((fila) => fila.id_evento && FECHA.test(String(fila.fecha_inicio).trim()))
  .map((fila) => {
    const inicio = String(fila.fecha_inicio).trim();
    const fin = FECHA.test(String(fila.fecha_fin).trim()) ? String(fila.fecha_fin).trim() : inicio;
    const estado = fin < hoy ? 'finalizado' : (inicio <= hoy ? 'en_curso' : 'proximo');
    return {
      id: fila.id_evento,
      titulo: fila.titulo,
      tipo: fila.tipo_evento,
      fecha_inicio: inicio,
      fecha_fin: fin,
      periodo: fila.periodo,
      dirigido_a: fila.dirigido_a,
      descripcion: fila.descripcion,
      estado,
      dias_para_inicio: Math.round((Date.parse(inicio) - Date.parse(hoy)) / DIA),
      es_demo: String(fila.es_demo).toUpperCase() === 'TRUE',
    };
  });

if (parametros.tipo_evento) {
  eventos = eventos.filter((evento) => evento.tipo === parametros.tipo_evento);
}
if (parametros.solo_proximos) {
  eventos = eventos.filter((evento) => evento.estado !== 'finalizado');
}
eventos.sort((a, b) => a.fecha_inicio.localeCompare(b.fecha_inicio));

const resultado = {
  hoy,
  fuente: 'Calendario académico en Google Sheets (datos DEMO)',
  filtro: { tipo_evento: parametros.tipo_evento, solo_proximos: parametros.solo_proximos },
  total: eventos.length,
  eventos: eventos.slice(0, 15),
};
if (parametros.tipo_solicitado && !parametros.tipo_evento) {
  resultado.aviso = `El tipo "${parametros.tipo_solicitado}" no existe; se muestran todos los tipos.`;
}
if (eventos.length === 0) {
  resultado.mensaje = 'No hay eventos que coincidan con la búsqueda en el calendario.';
}

return [{ json: resultado }];
